BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='45s';
DO $test$
DECLARE cafe uuid;actor uuid;warehouse uuid;party uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000001';cash uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000002';bank uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000003';sale uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000004';payment_id uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000005';pending_id uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000006';deleted_id uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000007';line_id uuid:=gen_random_uuid();purchase uuid:=gen_random_uuid();purchase_payment uuid:=gen_random_uuid();source_number bigint;payment_number bigint;result jsonb;detail jsonb;record jsonb;input jsonb;before_docs integer;before_journal integer;blocked boolean;checks integer:=0;other_actor uuid;refunded jsonb;refund_id uuid;
BEGIN
 SELECT id,owner_user_id INTO STRICT cafe,actor FROM public.cafes WHERE slug='test-cafe';SELECT id INTO STRICT warehouse FROM public.bf_warehouses WHERE cafe_id=cafe AND active ORDER BY id LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 IF EXISTS(SELECT 1 FROM public.bf_parties WHERE id=party) THEN RAISE EXCEPTION 'REHEARSAL fixture collision';END IF;
 INSERT INTO public.bf_parties(id,cafe_id,name,kind) VALUES(party,cafe,'Customer payments rollback fixture','customer');
 INSERT INTO public.bf_accounts(id,cafe_id,name,code,kind) VALUES(bank,cafe,'Payments rollback bank','PAY-ROLLBACK-BANK','bank');cash:=bank;
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,warehouse_id,account_id,subtotal,total,paid,note,created_by,tax_inclusive)
 VALUES(sale,cafe,'sale',party,warehouse,cash,200,200,50,'Customer payments rollback sale',actor,false) RETURNING number INTO source_number;
 INSERT INTO public.bf_document_lines(id,cafe_id,document_id,name,quantity,unit_price,net,tax,cost,activity_kind,vat_rate,tax_category) VALUES(line_id,cafe,sale,'Rollback service',10,20,200,0,0,'service',0,'O');
 PERFORM brand_finance_private.invoice_line(cafe,sale,cash,50,0,party,'Rollback collection');PERFORM brand_finance_private.invoice_line(cafe,sale,brand_finance_private.account(cafe,'1100'),150,0,party,'Rollback receivable');PERFORM brand_finance_private.invoice_line(cafe,sale,brand_finance_private.account(cafe,'4000'),0,200,party,'Rollback revenue');
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,total,paid,reference_id,note,created_by) VALUES(payment_id,cafe,'settlement',party,bank,75,75,sale,'Rollback payment',actor),(pending_id,cafe,'settlement',party,bank,20,20,sale,'Rollback pending',actor),(deleted_id,cafe,'settlement',party,bank,15,15,sale,'Rollback deleted',actor);
 PERFORM brand_finance_private.invoice_line(cafe,payment_id,bank,75,0,party,'Rollback collection');PERFORM brand_finance_private.invoice_line(cafe,payment_id,brand_finance_private.account(cafe,'1100'),0,75,party,'Rollback receivable');
 PERFORM brand_finance_private.invoice_line(cafe,pending_id,bank,20,0,party,'Rollback collection');PERFORM brand_finance_private.invoice_line(cafe,pending_id,brand_finance_private.account(cafe,'1100'),0,20,party,'Rollback receivable');
 PERFORM brand_finance_private.invoice_line(cafe,deleted_id,bank,15,0,party,'Rollback collection');PERFORM brand_finance_private.invoice_line(cafe,deleted_id,brand_finance_private.account(cafe,'1100'),0,15,party,'Rollback receivable');
 SELECT number INTO payment_number FROM public.bf_documents WHERE id=payment_id;
 INSERT INTO public.bf_documents(id,cafe_id,kind,warehouse_id,total,paid,created_by) VALUES(purchase,cafe,'purchase',warehouse,10,0,actor);
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,total,paid,reference_id,created_by) VALUES(purchase_payment,cafe,'settlement',party,bank,10,10,purchase,actor);
 detail:=public.brand_finance_customer_payments(cafe,pending_id);record:=detail->'payment';
 input:=jsonb_build_object('action','save','invoiceId',sale,'paymentId',pending_id,'revision',0,'requestId',gen_random_uuid(),'payload',jsonb_build_object('amount',20,'date',(now() AT TIME ZONE 'Asia/Riyadh')::date,'accountId',bank,'status','pending','collectorId',actor,'reference','PENDING-REF','details','Rollback pending note','receiptNote','Receipt note','attachments','[]'::jsonb));
 PERFORM public.brand_finance_manage_invoice_payment(cafe,input);
 PERFORM public.brand_finance_manage_invoice_payment(cafe,jsonb_build_object('action','delete','invoiceId',sale,'paymentId',deleted_id,'revision',0,'requestId',gen_random_uuid(),'reason','Rollback deleted payment'));
 SELECT count(*) INTO before_docs FROM public.bf_documents WHERE cafe_id=cafe;SELECT count(*) INTO before_journal FROM public.bf_journal WHERE cafe_id=cafe;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party));
 IF (result->>'total')::integer<>3 OR jsonb_array_length(result->'items')<>3 THEN RAISE EXCEPTION 'REHEARSAL default list includes deleted or supplier payment';END IF;checks:=checks+1;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result->'items') x WHERE x->>'invoiceStatus'<>'partial') THEN RAISE EXCEPTION 'REHEARSAL invoice status from single payment';END IF;checks:=checks+1;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result->'items') x WHERE (x->>'id')::uuid=sale AND (x->>'initial')::boolean AND x->'number'='null'::jsonb) THEN RAISE EXCEPTION 'REHEARSAL initial fabricated payment number';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'paymentNumber',lpad(payment_number::text,10,'0')));IF (result->>'total')::integer<>1 OR (result#>>'{items,0,id}')::uuid<>payment_id THEN RAISE EXCEPTION 'REHEARSAL payment number filter';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'paymentNumber',source_number::text));IF (result->>'total')::integer<>0 THEN RAISE EXCEPTION 'REHEARSAL invoice number treated as initial payment number';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'invoiceNumber',lpad(source_number::text,10,'0')));IF (result->>'total')::integer<>3 THEN RAISE EXCEPTION 'REHEARSAL invoice number filter';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'method','cash'));IF (result->>'total')::integer<>0 THEN RAISE EXCEPTION 'REHEARSAL method filter';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'status','pending'));IF (result->>'total')::integer<>1 OR (result#>>'{items,0,effectiveAmount}')::numeric<>0 OR result#>>'{items,0,reference}'<>'PENDING-REF' THEN RAISE EXCEPTION 'REHEARSAL pending effective amount';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'status','deleted'));IF (result->>'total')::integer<>1 OR (result#>>'{items,0,id}')::uuid<>deleted_id THEN RAISE EXCEPTION 'REHEARSAL deleted explicit filter';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'query','pending-ref'));IF (result->>'total')::integer<>1 THEN RAISE EXCEPTION 'REHEARSAL reference filter';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'sort','amount_desc','limit',1));IF (result#>>'{items,0,amount}')::numeric<>75 OR (result->>'total')::integer<>3 OR result#>'{items,0,details}' IS NOT NULL THEN RAISE EXCEPTION 'REHEARSAL compact amount sort page';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'sort','amount_asc','limit',1,'offset',1));IF (result#>>'{items,0,amount}')::numeric<>50 THEN RAISE EXCEPTION 'REHEARSAL sort offset';END IF;checks:=checks+1;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party,'from',((now() AT TIME ZONE 'Asia/Riyadh')::date+1)));IF (result->>'total')::integer<>0 THEN RAISE EXCEPTION 'REHEARSAL date filter';END IF;checks:=checks+1;
 detail:=public.brand_finance_customer_payments(cafe,payment_id);SELECT brand_finance_private.invoice_payment_record(s,i) INTO record FROM public.bf_documents s JOIN public.bf_documents i ON i.id=s.reference_id AND i.cafe_id=s.cafe_id WHERE s.id=payment_id;
 IF detail->'payment'<>record OR jsonb_array_length(detail#>'{detail,payments}')<>1 OR jsonb_array_length(detail#>'{detail,related}')<>1 OR detail#>'{detail,journal}'<>'[]'::jsonb OR detail#>'{detail,movements}'<>'[]'::jsonb OR (detail#>>'{detail,document,id}')::uuid<>sale THEN RAISE EXCEPTION 'REHEARSAL canonical compact detail';END IF;checks:=checks+1;
 detail:=public.brand_finance_customer_payments(cafe,sale);IF jsonb_array_length(detail#>'{detail,related}')<>0 OR NOT(detail#>>'{payment,initial}')::boolean THEN RAISE EXCEPTION 'REHEARSAL initial detail';END IF;checks:=checks+1;
 detail:=public.brand_finance_customer_payments(cafe,deleted_id);IF detail#>>'{payment,status}'<>'deleted' OR (detail#>>'{payment,canEdit}')::boolean OR (detail#>>'{payment,canDelete}')::boolean THEN RAISE EXCEPTION 'REHEARSAL deleted permissions';END IF;checks:=checks+1;
 IF public.brand_finance_customer_payments(cafe,purchase_payment) IS NOT NULL THEN RAISE EXCEPTION 'REHEARSAL supplier detail exposed';END IF;checks:=checks+1;
 IF (SELECT count(*) FROM public.bf_documents WHERE cafe_id=cafe)<>before_docs OR (SELECT count(*) FROM public.bf_journal WHERE cafe_id=cafe)<>before_journal THEN RAISE EXCEPTION 'REHEARSAL reading mutated finance';END IF;checks:=checks+1;
 input:=jsonb_set(jsonb_set(jsonb_set(input,'{paymentId}',to_jsonb(payment_id::text)),'{payload,amount}','150'),'{payload,status}','"completed"');input:=jsonb_set(input,'{requestId}',to_jsonb(gen_random_uuid()::text));
 PERFORM public.brand_finance_manage_invoice_payment(cafe,input);
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party));IF EXISTS(SELECT 1 FROM jsonb_array_elements(result->'items') x WHERE x->>'invoiceStatus'<>'paid') THEN RAISE EXCEPTION 'REHEARSAL corrected full invoice status';END IF;checks:=checks+1;
 detail:=public.brand_finance_customer_payments(cafe,payment_id);IF (detail#>>'{payment,amount}')::numeric<>150 OR (detail#>>'{payment,revision}')::integer<>1 THEN RAISE EXCEPTION 'REHEARSAL correction not current';END IF;checks:=checks+1;
 refunded:=public.brand_finance_execute(cafe,'refund',jsonb_build_object('documentId',sale,'lines',jsonb_build_array(jsonb_build_object('lineId',line_id,'quantity',10,'expectedReturnedQuantity',0)),'expectedTotal',200,'expectedPaid',200,'paymentMethod','bank','accountId',bank,'note','Customer payments returned status'),gen_random_uuid());
 refunded:=public.brand_finance_execute(cafe,'refund_approve',jsonb_build_object('requestId',refunded->>'id','expectedTotal',200,'expectedPaid',200),gen_random_uuid());refund_id:=(refunded->>'id')::uuid;
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party));IF (result->>'total')::integer<>3 OR EXISTS(SELECT 1 FROM jsonb_array_elements(result->'items') x WHERE x->>'invoiceStatus'<>'returned' OR (x->>'id')::uuid=refund_id) THEN RAISE EXCEPTION 'REHEARSAL refund shown as customer payment or incorrect invoice status';END IF;checks:=checks+1;
 IF public.brand_finance_customer_payments(cafe,refund_id) IS NOT NULL THEN RAISE EXCEPTION 'REHEARSAL refund detail treated as payment';END IF;checks:=checks+1;
 SELECT p.id INTO other_actor FROM public.profiles p WHERE p.status='active' AND p.id<>actor AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=cafe AND s.user_id=p.id) LIMIT 1;IF other_actor IS NULL THEN RAISE EXCEPTION 'REHEARSAL no actor fixture';END IF;
 INSERT INTO public.bf_staff(cafe_id,user_id,name,role) VALUES(cafe,other_actor,'Payments rollback auditor','auditor');PERFORM set_config('request.jwt.claim.sub',other_actor::text,true);
 detail:=public.brand_finance_customer_payments(cafe,payment_id);IF (detail#>>'{payment,canEdit}')::boolean OR (detail#>>'{payment,canDelete}')::boolean THEN RAISE EXCEPTION 'REHEARSAL auditor write permissions';END IF;checks:=checks+1;
 UPDATE public.bf_staff SET role='warehouse' WHERE cafe_id=cafe AND user_id=other_actor;
 blocked:=false;BEGIN PERFORM public.brand_finance_customer_payments(cafe,payment_id);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL warehouse read';END IF;checks:=checks+1;
 UPDATE public.bf_staff SET active=false WHERE cafe_id=cafe AND user_id=other_actor;blocked:=false;BEGIN PERFORM public.brand_finance_customer_payments(cafe);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL revoked staff read';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub','',true);blocked:=false;BEGIN PERFORM public.brand_finance_customer_payments(cafe);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL anonymous read';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);blocked:=false;BEGIN PERFORM public.brand_finance_customer_payments('a3f635f7-3164-4ec6-9f09-27ac6d000099',NULL);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'REHEARSAL cross tenant read';END IF;checks:=checks+1;
 IF has_function_privilege('anon','public.brand_finance_customer_payments(uuid,uuid,jsonb)','EXECUTE') OR has_function_privilege('service_role','public.brand_finance_customer_payments(uuid,uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'REHEARSAL RPC grants';END IF;checks:=checks+1;
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM set_config('branda.customer_payments_rehearsal',jsonb_build_object('ok',true,'checks',checks,'partyId',party,'scope','rollback transaction only')::text,true);
END $test$;
DO $zero_initial$
DECLARE cafe uuid;actor uuid;party uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000001';bank uuid:='a3f635f7-3164-4ec6-9f09-27ac6d000003';sale uuid:=gen_random_uuid();payment uuid:=gen_random_uuid();result jsonb;checks integer:=0;
BEGIN
 SET CONSTRAINTS ALL DEFERRED;
 SELECT id,owner_user_id INTO STRICT cafe,actor FROM public.cafes WHERE slug='test-cafe';
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,subtotal,total,paid,created_by,tax_inclusive) VALUES(sale,cafe,'sale',party,100,100,0,actor,false);
 INSERT INTO public.bf_document_lines(cafe_id,document_id,name,quantity,unit_price,net,tax,cost,activity_kind,vat_rate,tax_category) VALUES(cafe,sale,'Unpaid rollback service',1,100,100,0,0,'service',0,'O');
 PERFORM brand_finance_private.invoice_line(cafe,sale,brand_finance_private.account(cafe,'1100'),100,0,party,'Rollback receivable');PERFORM brand_finance_private.invoice_line(cafe,sale,brand_finance_private.account(cafe,'4000'),0,100,party,'Rollback revenue');
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party));IF (result->>'total')::integer<>3 OR public.brand_finance_customer_payments(cafe,sale) IS NOT NULL THEN RAISE EXCEPTION 'REHEARSAL wholly unpaid invoice shown as payment';END IF;checks:=checks+1;
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,total,paid,reference_id,created_by) VALUES(payment,cafe,'settlement',party,bank,20,20,sale,actor);
 PERFORM brand_finance_private.invoice_line(cafe,payment,bank,20,0,party,'Rollback collection');PERFORM brand_finance_private.invoice_line(cafe,payment,brand_finance_private.account(cafe,'1100'),0,20,party,'Rollback receivable');
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party));IF (result->>'total')::integer<>4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(result->'items') x WHERE (x->>'id')::uuid=sale) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result->'items') x WHERE (x->>'id')::uuid=payment AND x->>'invoiceStatus'='partial') THEN RAISE EXCEPTION 'REHEARSAL later collection fabricated zero initial payment';END IF;checks:=checks+1;
 PERFORM public.brand_finance_manage_invoice_payment(cafe,jsonb_build_object('action','save','invoiceId',sale,'paymentId',payment,'revision',0,'requestId',gen_random_uuid(),'payload',jsonb_build_object('amount',20,'date',(now() AT TIME ZONE 'Asia/Riyadh')::date,'accountId',bank,'status','pending','collectorId',actor,'reference','','details','','receiptNote','','attachments','[]'::jsonb)));
 result:=public.brand_finance_customer_payments(cafe,NULL,jsonb_build_object('partyId',party));IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result->'items') x WHERE (x->>'id')::uuid=payment AND x->>'invoiceStatus'='unpaid' AND (x->>'effectiveAmount')::numeric=0) THEN RAISE EXCEPTION 'REHEARSAL pending payment mislabeled invoice paid';END IF;checks:=checks+1;
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM set_config('branda.customer_payments_rehearsal',(current_setting('branda.customer_payments_rehearsal')::jsonb||jsonb_build_object('checks',(current_setting('branda.customer_payments_rehearsal')::jsonb->>'checks')::integer+checks))::text,true);
END $zero_initial$;
SELECT current_setting('branda.customer_payments_rehearsal')::jsonb AS verification;

ROLLBACK;
